import jax.numpy as jnp
import flax.linen as nn
from jax import random
from typing import Dict, Any, Sequence

class MultiKernelCNN(nn.Module):
    """A 1D CNN with multiple kernel sizes for RNA sequence modeling."""
    d_output: int
    task_type: str
    num_filters: int = 128
    kernel_sizes: Sequence[int] = (3, 5, 7)
    dropout_rate: float = 0.25

    @nn.compact
    def __call__(self, x, deterministic=True):
        # x shape: (batch, seq_len, 4)

        conv_outputs = []
        for kernel_size in self.kernel_sizes:
            conv_out = nn.Conv(
                features=self.num_filters,
                kernel_size=(kernel_size,),
                padding='SAME'
            )(x)
            conv_outputs.append(conv_out)

        x = jnp.concatenate(conv_outputs, axis=-1)
        x = nn.relu(x)
        x = nn.Dropout(rate=self.dropout_rate)(x, deterministic=deterministic)

        x = jnp.mean(x, axis=1)

        x = nn.Dense(features=self.d_output)(x)

        if self.task_type == "regression":
            return x.squeeze(-1)
        else:
            return x

class CNNetworkWrapper:
    """Wrapper for the CNN to match the required interface."""
    def __init__(self, d_output: int, task_type: str, num_filters: int, kernel_sizes: Sequence[int], dropout_rate: float):
        self.network = MultiKernelCNN(
            d_output=d_output,
            task_type=task_type,
            num_filters=num_filters,
            kernel_sizes=kernel_sizes,
            dropout_rate=dropout_rate
        )

    def init(self, rng_key, dummy_input):
        params_key, dropout_key = random.split(rng_key)
        variables = self.network.init({'params': params_key, 'dropout': dropout_key},
                                     dummy_input, deterministic=True)
        return variables['params']

    def apply(self, params, x, deterministic=True, rng_key=None):
        if not deterministic and rng_key is None:
            rng_key = random.PRNGKey(0)

        return self.network.apply(
            {'params': params}, 
            x, 
            deterministic=deterministic, 
            rngs={'dropout': rng_key} if not deterministic else None
        )

def create_network(hparams: Dict[str, Any]):
    """Creates the Multi-Kernel CNN network."""
    return CNNetworkWrapper(
        d_output=hparams.get("d_output"),
        task_type=hparams.get("task_type"),
        num_filters=hparams.get("num_filters"),
        kernel_sizes=hparams.get("kernel_sizes"),
        dropout_rate=hparams.get("dropout_rate")
    )

def _define_hyperparameters():
    return {
        'learning_rate': 0.001,
        'num_filters': 128,
        'kernel_sizes': [3, 5, 7],
        'dropout_rate': 0.25
    }
